import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"7. Criterion-Level Results","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.5/part-03.md","filePath":"en/publications/implementation-case-i0.5/part-03.md","lastUpdated":1785916356000}'),d={name:"en/publications/implementation-case-i0.5/part-03.md"};function r(o,e,s,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_7-criterion-level-results" tabindex="-1">7. Criterion-Level Results <a class="header-anchor" href="#_7-criterion-level-results" aria-label="Permalink to &quot;7. Criterion-Level Results&quot;">​</a></h1><p>The test names and meanings below are direct references to Core Specification Section 10.2; this report records only product evidence and remaining gaps.</p><table tabindex="0"><thead><tr><th>ID</th><th>Canonical test name</th><th>Verdict</th><th>Product evidence and remaining gap</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td>PARTIAL</td><td>FCoP and CodeFlowMu provide schemas and validation paths, but complete TMPA canonical-object coverage and all negative format cases are not yet exposed through one Core validator.</td></tr><tr><td>C02</td><td>Primary-carrier and single-writer immutability</td><td>PARTIAL</td><td>Separate artifacts and correction evidence exist; stricter immutable-object and one-primary-carrier observation remains incomplete.</td></tr><tr><td>C03</td><td>Duplicate object identity</td><td>PARTIAL</td><td>Duplicate and conflict mechanisms exist locally, but a canonical same-ID/different-content quarantine view is not exposed end to end.</td></tr><tr><td>C04</td><td>Serial-stream continuity and asynchronous progress</td><td>PARTIAL</td><td>Local ordering, dependency waiting, and asynchronous progress are implemented; one canonical partial-order graph and stream-gap issue set are not yet emitted.</td></tr><tr><td>C05</td><td>Role authority</td><td>PARTIAL</td><td>Role, capability, and operation gates exist; all failures are not yet normalized into one authoritative TMPA issue model.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td>PARTIAL</td><td>Direct lifecycle tests cover illegal and unauthorized transitions, but the product evidence does not yet emit both required canonical outputs: <code>ILLEGAL_TRANSITION</code>/<code>invalid</code> and <code>LIFECYCLE_UNDETERMINED</code>/<code>undetermined</code>.</td></tr><tr><td>C07</td><td>Separation of duties</td><td>PARTIAL</td><td>Separate reports and reviews plus review gates exist, but complete identity-level separation and exception-object handling are not fully demonstrated.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td>NOT RUN</td><td>Fixture oracle exists; product covered-content digest verification and canonical tamper reader were not executed.</td></tr><tr><td>C09</td><td>Missing reference</td><td>PARTIAL</td><td>Missing dependencies can block work, but the complete <code>undetermined</code>/partial graph propagation and canonical issue output remain incomplete.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td>NOT RUN</td><td>Prohibited-cycle fixture exists; product graph reader capable of quarantining only the affected subgraph was not available.</td></tr><tr><td>C11</td><td>Aggregation and reconstruction determinism</td><td>NOT RUN</td><td>The fixture oracle produced byte-equivalent output across 24 permutations; no product-level canonical graph-plus-issue serializer was available.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td>NOT RUN</td><td>Conflict-preservation fixture exists; product-level deterministic disputed/<code>undetermined</code> view and authorized resolution path were not executed as one criterion.</td></tr><tr><td>C13</td><td>Recovery</td><td>PARTIAL</td><td>Restart and recovery mechanisms exist, but no unified fresh reader reconstructs all responsibility, lifecycle, dependency, and issue state.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td>PASS</td><td>Direct archive/history tests preserve terminal state, transitions, prior reports, reviews, and task evidence.</td></tr></tbody></table><p>The separate S0.4 Reference Reader track passes all 14 synthetic fixture assertions. Those results validate the executable interpretation and deterministic runner, not the products listed in the table.</p><h1 id="_8-product-projection-gap" tabindex="-1">8. Product Projection Gap <a class="header-anchor" href="#_8-product-projection-gap" aria-label="Permalink to &quot;8. Product Projection Gap&quot;">​</a></h1><p>The publication repository now contains a generic S0.4 read-only Reference Reader. The dominant product gap is therefore narrower and more concrete: neither pinned product has a maintained projection adapter that converts its native artifacts into the S0.4 source-object surface consumed by that reader.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source artifacts</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>source candidates with retained provenance</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>canonical candidate set</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>partial-order process and responsibility graph</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>canonical issue set</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>valid / invalid / undetermined judgment</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>authoritative / quarantined / partial / disputed / pending_human view</span></span></code></pre></div><p>FCoP and CodeFlowMu already provide substantial write-side and local-control mechanisms: separate artifacts, atomic publication, role checks, lifecycle gates, dependency blocking, archive preservation, and restart recovery. Product-specific projection would directly improve C03, C05, C09, and C13, provide infrastructure for C04/C07, and create the product execution path required by C10–C12. C01 still has schema-coverage gaps; C02 has a stricter immutability gap; C06 lacks the complete canonical three-valued output pair; C08 requires covered-content digest evidence. CodeFlowMu additionally needs a publicly retrievable pinned source or reproduction package.</p><h1 id="_9-three-valued-governance-in-the-worked-flow" tabindex="-1">9. Three-Valued Governance in the Worked Flow <a class="header-anchor" href="#_9-three-valued-governance-in-the-worked-flow" aria-label="Permalink to &quot;9. Three-Valued Governance in the Worked Flow&quot;">​</a></h1><p>TMPA distinguishes semantic judgment from view classification:</p><table tabindex="0"><thead><tr><th>Semantic judgment</th><th>View classification</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>required evidence and rules establish the conclusion</td></tr><tr><td><code>invalid</code></td><td>quarantined or rejected</td><td>a deterministic violation excludes the affected evidence or action</td></tr><tr><td><code>undetermined</code></td><td>partial</td><td>required evidence is missing or incomplete</td></tr><tr><td><code>undetermined</code></td><td>disputed</td><td>valid evidence conflicts and no authorized resolution exists</td></tr><tr><td><code>undetermined</code></td><td>pending_human</td><td>the applicable profile requires a human decision</td></tr></tbody></table><p>A representative review flow is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK → REPORT → QA REVIEW(needs_human)</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>          judgment: undetermined</span></span>
<span class="line"><span>          view: pending_human</span></span>
<span class="line"><span>          lifecycle: blocked_pending_resolution</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>              ADMIN DECISION</span></span>
<span class="line"><span>             ↙              ↘</span></span>
<span class="line"><span>        approve             reject</span></span>
<span class="line"><span>          ↓                   ↓</span></span>
<span class="line"><span>        valid              invalid</span></span></code></pre></div><p>The <code>needs_human</code> state remains present in the graph and queryable. It is not prematurely represented as done, approved, failed, or rejected. Any downstream object that depends on the unresolved review remains <code>undetermined</code> until an authorized decision object is added.</p><p>The S0.4 Reference Reader demonstrates this three-valued flow on synthetic fixtures. Current CodeFlowMu behavior includes human-attention and waiting states, but product normalization into the Core judgment/view model remains an implementation target rather than a fully demonstrated product claim.</p><h1 id="_10-wp-13-multi-agent-evidence-gating-under-uncertain-tool-results" tabindex="-1">10. WP-13: Multi-Agent Evidence Gating under Uncertain Tool Results <a class="header-anchor" href="#_10-wp-13-multi-agent-evidence-gating-under-uncertain-tool-results" aria-label="Permalink to &quot;10. WP-13: Multi-Agent Evidence Gating under Uncertain Tool Results&quot;">​</a></h1><h2 id="_10-1-research-question-and-unit-of-observation" tabindex="-1">10.1 Research Question and Unit of Observation <a class="header-anchor" href="#_10-1-research-question-and-unit-of-observation" aria-label="Permalink to &quot;10.1 Research Question and Unit of Observation&quot;">​</a></h2><p>WP-13 records a field event with direct relevance to TMPA three-valued governance. A subexecution produced a completion-meaning summary after its tool lifecycle ended, while the same raw event retained <code>no exit status</code>, unconfirmed tests, and an unavailable commit SHA. The research question is not why a model produced an inaccurate sentence. It is:</p><blockquote><p>When an agent claim and persistent work facts do not close, can multi-agent governance prevent the unverified claim from entering the authoritative delivery chain?</p></blockquote><p>The observation window is 2026-08-05 12:59–13:11 (Asia/Shanghai). The public evidence set preserves two tasks, DEV and QA reports, the raw subexecution JSONL, a 300-line runtime excerpt, a Git patch and manifest, five QA JSON files, a session transcript, and explicit boundary notes. It is author-produced engineering evidence, not a third-party audit.</p><h2 id="_10-2-from-unconfirmed-claim-to-reviewable-delivery" tabindex="-1">10.2 From Unconfirmed Claim to Reviewable Delivery <a class="header-anchor" href="#_10-2-from-unconfirmed-claim-to-reviewable-delivery" aria-label="Permalink to &quot;10.2 From Unconfirmed Claim to Reviewable Delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Observable fact</th><th>Governance result</th></tr></thead><tbody><tr><td>DEV subexecution</td><td>the tool event ended, but inner commands lacked confirmed exit status; tests and SHA were unconfirmed</td><td>tool completion did not establish business completion</td></tr><tr><td>PM fact check</td><td>no formal DEV report, required test files absent, and Git HEAD still at the previous work package</td><td>no release, no QA dispatch, and no duplicate task</td></tr><tr><td>Same-task recovery</td><td>after tool-channel recovery, DEV completed implementation, tests, commit <code>609571dd…</code>, and <code>REPORT-037</code></td><td>delivery acquired externally checkable facts</td></tr><tr><td>Role-separated QA</td><td><code>QA-01</code> reran 27 tests, typecheck, and diff check against <code>DEV-01</code> delivery</td><td>27/27 PASS; typecheck 0; diff check 0</td></tr></tbody></table><p>This chain does not show that the model ceased making errors. It demonstrates <strong>governance-layer containment</strong>: natural-language claims remain candidate evidence, and they do not change authoritative delivery state until task, report, Git, and test facts close.</p><h2 id="_10-3-tmpa-three-valued-interpretation" tabindex="-1">10.3 TMPA Three-Valued Interpretation <a class="header-anchor" href="#_10-3-tmpa-three-valued-interpretation" aria-label="Permalink to &quot;10.3 TMPA Three-Valued Interpretation&quot;">​</a></h2><p>In a retrospective S0.4 analysis of observation time <code>τ₀</code>, the conclusion &quot;WP-13 is complete&quot; should not be <code>valid</code>, because mandatory evidence was absent or unreadable. It should not automatically be <code>invalid</code>, because the implementation itself had not yet been proven to violate acceptance rules. The appropriate semantic value is <code>undetermined</code>, with a <code>partial</code> operational view; PM waits for evidence and does not release.</p><p>This is an analytical S0.4 projection of field evidence, not a claim that CodeFlowMu emitted a canonical Reader envelope at the time. The native system did not publish <code>LIFECYCLE_UNDETERMINED</code>, a canonical issue set, and a three-valued result bound to a fixed profile. The case therefore does not upgrade C06 to PASS.</p><h2 id="_10-4-tmpa-to-fcop-to-codeflowmu" tabindex="-1">10.4 TMPA to FCoP to CodeFlowMu <a class="header-anchor" href="#_10-4-tmpa-to-fcop-to-codeflowmu" aria-label="Permalink to &quot;10.4 TMPA to FCoP to CodeFlowMu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Realization in this case</th></tr></thead><tbody><tr><td>TMPA</td><td>separates claims, evidence, and authoritative judgment; incomplete mandatory evidence remains <code>undetermined</code></td></tr><tr><td>FCoP</td><td>TASK is the stable primary carrier, REPORT is published separately, and <code>references</code>/<code>depends_on</code> retain task-report relations</td></tr><tr><td>CodeFlowMu</td><td>runtime records tool events and task state; PM performs business fact checking; DEV resumes the original task; QA verifies under a separate role</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Evidence dimension</th><th>Specified</th><th>Implemented</th><th>Demonstrated</th><th>Independently Adopted</th></tr></thead><tbody><tr><td>three-valued judgment under incomplete evidence</td><td>S0.4</td><td>local waiting/review controls exist</td><td>WP-13 retrospective analysis</td><td>no</td></tr><tr><td>persistent TASK/REPORT fact chain</td><td>FCoP profile</td><td>yes</td><td>yes</td><td>no</td></tr><tr><td>DEV–PM–QA separation of duties</td><td>S0.4/FCoP profile</td><td>yes</td><td><code>DEV-01</code>/PM/<code>QA-01</code></td><td>no</td></tr><tr><td>same-task recovery and evidence completion</td><td>S0.4 recovery objective</td><td>yes</td><td>yes</td><td>no</td></tr><tr><td>WP-13 product projection adapter and canonical Reader output</td><td>S0.4</td><td>no</td><td>no</td><td>no</td></tr></tbody></table><h2 id="_10-5-contribution-to-c01–c14-evidence" tabindex="-1">10.5 Contribution to C01–C14 Evidence <a class="header-anchor" href="#_10-5-contribution-to-c01–c14-evidence" aria-label="Permalink to &quot;10.5 Contribution to C01–C14 Evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>Incremental WP-13 evidence</th><th>I0.5 verdict effect</th></tr></thead><tbody><tr><td>C04</td><td>TASK-019 → REPORT-037 → TASK-020 → REPORT-038 plus runtime events form a traceable serial chain</td><td>strengthens demonstrated evidence; remains PARTIAL</td></tr><tr><td>C06</td><td>authoritative delivery state does not advance while mandatory evidence is insufficient</td><td>no canonical issue code or Reader result; remains PARTIAL</td></tr><tr><td>C07</td><td>DEV delivery, PM fact checking, and QA verification occur under separate work roles</td><td>field demonstration of role separation; authenticated identity and exception objects remain missing, so PARTIAL</td></tr><tr><td>C09</td><td>required report, commit, and test evidence is missing at the intermediate observation</td><td>supports incomplete-evidence analysis but emits no canonical <code>MISSING_REFERENCE</code>; remains PARTIAL</td></tr><tr><td>C13</td><td>after tool recovery, the original task continues and adds Git, report, and QA evidence</td><td>strengthens recovery evidence; no fresh-reader equivalence, so PARTIAL</td></tr><tr><td>C08/C11/C12</td><td>unsigned checksums, raw/readable projection comparison, and retained conflicting claims are supporting materials</td><td>do not substitute for product-criterion execution; remain NOT RUN</td></tr></tbody></table><p>The case adds no adjudicable evidence for the remaining criteria. I0.5 therefore preserves the I0.4 aggregate product result and does not relabel prior unexecuted criteria.</p><h2 id="_10-6-evidence-boundaries" tabindex="-1">10.6 Evidence Boundaries <a class="header-anchor" href="#_10-6-evidence-boundaries" aria-label="Permalink to &quot;10.6 Evidence Boundaries&quot;">​</a></h2><ul><li>QA is role-separated verification, not external third-party independent validation.</li><li><code>dev-report-037.md</code> and <code>qa-report-038.md</code> retain <code>runtime_bound: False</code>; they are not runtime-authenticated evidence.</li><li>At the evidence snapshot endpoint, TASK-019 and TASK-020 are both <code>review / pending</code>. The package establishes DEV delivery and role-separated QA PASS, not terminal approval or archive within the snapshot.</li><li>Same-bundle unsigned checksums establish only internal consistency, not publisher identity, source authenticity, or a trusted timestamp.</li><li>The case demonstrates containment of an unverified completion claim, not prevention or elimination of all model hallucinations.</li></ul><p>The complete byte-preserved package is downloadable as <a href="/joinwell52/evidence/tmpa/i0.5/wp13-multi-agent-fact-check-publication-evidence-v3.zip">WP-13 Publication Evidence V3</a>, with outer SHA-256 <code>5b5eda3034c822f13421783244b1d0c76a9fa79950bfad0ce61bb8d2e404131c</code>.</p><h1 id="_11-reproducibility-and-limitations" tabindex="-1">11. Reproducibility and Limitations <a class="header-anchor" href="#_11-reproducibility-and-limitations" aria-label="Permalink to &quot;11. Reproducibility and Limitations&quot;">​</a></h1><p>The S0.4 corpus is now public at a stable repository path and includes one-command execution, schemas, profile, fixtures, assertions, outputs, logs, and SHA-256 manifests. Repeated local executions with the fixed execution timestamp produce byte-identical artifacts. The FCoP commit was independently retrieved within this maintenance run and its selected test suites reran successfully; the CodeFlowMu commit was unavailable from the public repository. No third party has rerun or independently validated the corpus.</p><p>The baseline does not establish representative SME performance, comparative deployment cost, broad fault tolerance, independent adoption, factual truth of participant claims, authenticated identity, protected storage, or Byzantine resilience. Product and case evidence remain author-produced. The public demonstration and private data-producing system are not asserted to be one reproducible public build.</p><p>Required next measurements include installation dependencies and time, first-team startup, CPU/memory/storage growth, reconstruction under delayed and permuted evidence, controlled interruption and restart, conflict and missing-reference injection, human inspectability, adoption burden, and comparison against chat/shared-folder/simple-workflow baselines.</p><h1 id="_12-engineering-roadmap" tabindex="-1">12. Engineering Roadmap <a class="header-anchor" href="#_12-engineering-roadmap" aria-label="Permalink to &quot;12. Engineering Roadmap&quot;">​</a></h1><ol><li>Implement maintained FCoP and CodeFlowMu projection adapters without changing existing write behavior.</li><li>Publish or otherwise make the pinned CodeFlowMu source and reproduction package retrievable.</li><li>Execute product-level C08, C10, C11, and C12.</li><li>Emit the missing canonical outputs for C01–C07, C09, and C13, including both C06 three-valued branches.</li><li>Measure low-resource deployment, restart, and incremental reconstruction.</li><li>Obtain an independent rerun and record all differences.</li></ol><h1 id="_13-evidence-statement" tabindex="-1">13. Evidence Statement <a class="header-anchor" href="#_13-evidence-statement" aria-label="Permalink to &quot;13. Evidence Statement&quot;">​</a></h1><p>This report provides versioned engineering evidence, not independent validation. Its strongest results are bounded: the public S0.4 Reference Reader passes 14 of 14 synthetic criteria; the pinned product baseline has C14 PASS, nine PARTIAL verdicts, four NOT RUN verdicts, and no observed FAIL. Zero FAIL does not mean complete conformance because four product criteria were not executed and nine remain incomplete. Stronger claims require product projection, CodeFlowMu reproducibility, broader experiments, and independent reproduction.</p>`,43)])])}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
